import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.00tzVH5c.js";var i=JSON.parse(`{"title":"What is BullMQ","description":"General description of BullMQ and its features","frontmatter":{"description":"General description of BullMQ and its features"},"headers":[],"relativePath":"index.md","filePath":"README.md","lastUpdated":1687950428000}`),a={name:`index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-bullmq" tabindex="-1">What is BullMQ <a class="header-anchor" href="#what-is-bullmq" aria-label="Permalink to “What is BullMQ”">​</a></h1><p>BullMQ is a <a href="https://nodejs.org" target="_blank" rel="noreferrer">Node.js</a> library that implements a fast and robust queue system built on top of <a href="https://redis.io" target="_blank" rel="noreferrer">Redis</a> that helps in resolving many modern age micro-services architectures.</p><p>The library is designed so that it will fulfill the following goals:</p><ul><li>Exactly once queue semantics, i.e., attempts to deliver every message exactly one time, but it will deliver at least once in the worst case scenario*.</li><li>Easy to scale horizontally. Add more workers for processing jobs in parallel.</li><li>Consistent.</li><li>High performant. Try to get the highest possible throughput from Redis by combining efficient .lua scripts and pipelining.</li></ul><p>View the repository, see open issues, and contribute back <a href="https://github.com/taskforcesh/bullmq" target="_blank" rel="noreferrer">on GitHub</a>!</p><h2 id="features" tabindex="-1"><strong>Features</strong> <a class="header-anchor" href="#features" aria-label="Permalink to “Features”">​</a></h2><p>If you are new to Message Queues, you may wonder why they are needed after all. Queues can solve many different problems in an elegant way, from smoothing out processing peaks to creating robust communication channels between micro-services or offloading heavy work from one server to many smaller workers, and many other use cases. Check the <a href="./patterns/adding-bulks">Patterns</a> section for getting some inspiration and information about best practices.</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-0"><strong>Minimal CPU usage due to a polling-free design</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-1"><strong>Distributed job execution based on Redis</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-2"><strong>LIFO and FIFO jobs</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-3"><strong>Priorities</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-4"><strong>Delayed jobs</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-5"><strong>Scheduled and repeatable jobs according to cron specifications</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-6"><strong>Retries of failed jobs</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-7"><strong>Concurrency setting per worker</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-8" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-8"><strong>Threaded (sandboxed) processing functions</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-9" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-9"><strong>Automatic recovery from process crashes</strong></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-10" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-10"><strong>Parent-Child dependencies</strong></label></li></ul><h3 id="used-by" tabindex="-1">Used by <a class="header-anchor" href="#used-by" aria-label="Permalink to “Used by”">​</a></h3><p>BullMQ is used by many organizations big and small, here are some notable examples:</p><p><img src="/assets/clipart1565701.DERORiJq.png" alt="" width="758" height="171"></p><p><img src="/assets/wordmark-logo.ChPgPeki.png" alt="" width="1200" height="269"></p><p><img src="/assets/datawrapper-logo.D8coLFwh.png" alt="" width="446" height="180"></p><p><img src="data:image/png;base64," alt="" width="320" height="60"></p>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};